def write_json_records_C10(json_export_file) -> None:
    """Writes individual JSON records."""
    ws_first_record = 'N'
    ws_eof_flag = 'N'

    while ws_eof_flag != 'Y':
        try:
            ws_daily_sum_rec = read_daily_summary_file()
            format_json_record_C10(json_export_file, ws_daily_sum_rec, ws_first_record)
            ws_first_record = 'Y'
        except EOFError:
            ws_eof_flag = 'Y'
    ws_eof_flag = 'N'

def format_json_record_C10(json_export_file, ws_daily_sum_rec, ws_first_record) -> None:
    """Formats and writes a single JSON record."""

    daily_date = ws_daily_sum_rec.daily_date
    daily_trans_count = ws_daily_sum_rec.daily_trans_count
    daily_trans_amount = ws_daily_sum_rec.daily_trans_amount

    if ws_first_record == 'Y':
        ws_json_comma = ','
    else:
        ws_json_comma = ''
        ws_first_record = 'Y'
    ws_json_line = f'{ws_json_comma}{{"date":"{daily_date}","transCount":{daily_trans_count},"transAmount":{daily_trans_amount}}}'
    write_json_record(json_export_file, ws_json_line)

