def check_activity_C10(ws_account_rec) -> None:
    """Checks account activity."""
    ws_process_date = '20240101'
    acct_last_activity = ws_account_rec.acct_last_activity
    ws_days_inactive = int(ws_process_date) - int(acct_last_activity)
    if ws_days_inactive > 365:
        ws_account_rec.acct_status = 'D'
        mark_dormant_C10(ws_account_rec)

def mark_dormant_C10(ws_account_rec) -> None:
    """Marks an account as dormant."""
    ws_account_rec.acct_status_desc = 'DORMANT'
