def account_closure_C10() -> None:
    """Handles account closure requests."""
    ws_close_request = 'Y' # Place holder
    if ws_close_request == 'Y':
        ws_account_rec = AccountRecord()
        validate_closure_C10(ws_account_rec)
        if ws_closure_valid == 'Y':
            process_closure_C10(ws_account_rec)
        else:
            reject_closure_C10()

def validate_closure_C10(ws_account_rec) -> None:
    """Validates an account closure request."""
    global ws_closure_valid
    global ws_closure_reject
    ws_closure_valid = 'Y'
    if ws_account_rec.acct_balance < 0:
        ws_closure_valid = 'N'
        ws_closure_reject = 'NEGATIVE BALANCE'
    if ws_account_rec.acct_pending_trans > 0:
        ws_closure_valid = 'N'
        ws_closure_reject = 'PENDING TRANSACTIONS'
    if ws_account_rec.acct_loan_link != ' ':
        ws_closure_valid = 'N'
        ws_closure_reject = 'LINKED LOAN EXISTS'
        
ws_closure_valid = 'Y' # place holder
ws_closure_reject = 'NO_REASON' # Place holder

