@dataclass
class WsReconExceptionC15:
    """ws_recon_exception data structure."""
    recon_exc_account: str = ""
    recon_exc_diff: Decimal = Decimal('0')
    recon_exc_date: str = ""

recon_exception_record: str = ""

ws_gl_account: str = ""

def log_recon_exception_C15(ws_gl_account: str, ws_recon_diff: Decimal) -> None:
    """Logs a reconciliation exception."""
    ws_recon_exception: WsReconExceptionC15 = WsReconExceptionC15()
    ws_recon_exception.recon_exc_account = ws_gl_account
    ws_recon_exception.recon_exc_diff = ws_recon_diff
    ws_recon_exception.recon_exc_date = current_date()
    write_recon_exception_record(ws_recon_exception)

def current_date() -> str:
    """Returns the current date."""
    pass

def write_recon_exception_record(ws_recon_exception: WsReconExceptionC15) -> None:
    """Writes the reconciliation exception record."""
    global recon_exception_record
    recon_exception_record = str(ws_recon_exception)

def intercompany_recon_C15() -> None:
    """Performs intercompany reconciliation."""
    load_ic_balances_C15()
    match_ic_pairs_C15()
    report_ic_differences_C15()

ws_eof_flag: str = ""
ws_ic_balance: str = ""
intercompany_file: str = ""
ws_ic_array: List[str] = []
ws_ic_count: int = 0

def load_ic_balances_C15() -> None:
    """Loads intercompany balances from file."""
    global ws_eof_flag, ws_ic_count
    ws_ic_count = 0
    ws_eof_flag = 'N'
    while ws_eof_flag != 'Y':
        ic_balance = read_intercompany_file()
        if ic_balance is None:
            ws_eof_flag = 'Y'
        else:
            ws_ic_count += 1
            ws_ic_array.append(ic_balance)
    ws_eof_flag = 'N'

