def match_ic_pairs_C15() -> None:
    """Matches intercompany pairs."""
    global ws_ic_idx
    ws_ic_idx = 1
    while ws_ic_idx <= ws_ic_count:
        find_ic_counterpart_C15(ws_ic_idx)
        ws_ic_idx += 1

ic_from_entity: List[str] = []
ic_to_entity: List[str] = []

ws_search_from: str = ""
ws_search_to: str = ""
ws_ic_idx2: int = 0

ic_amount: List[Decimal] = []

def find_ic_counterpart_C15(ws_ic_idx: int) -> None:
    """Finds the intercompany counterpart for a given index."""
    global ws_search_from, ws_search_to, ws_ic_idx2
    ws_search_from = ic_from_entity[ws_ic_idx - 1]
    ws_search_to = ic_to_entity[ws_ic_idx - 1]
    ws_ic_idx2 = 1
    while ws_ic_idx2 <= ws_ic_count:
        if ic_from_entity[ws_ic_idx2 - 1] == ws_search_to:
            if ic_to_entity[ws_ic_idx2 - 1] == ws_search_from:
                ws_ic_diff: Decimal = ic_amount[ws_ic_idx - 1] + ic_amount[ws_ic_idx2 - 1]
                if ws_ic_diff != Decimal('0'):
                    log_ic_diff_C15(ws_search_from, ws_search_to, ws_ic_diff)
                break
        ws_ic_idx2 += 1

